# Select the correct folder (get the current time and date and find that folder)
#   this is what I will look at

# Loop throuygh the month folders in the main year folder
# loop through each file within each month (file type should not matter)

# Check the text within that folder contains ".ai" which can be attached to any other parts
# can also use a check for:
# - "CLAUDE", "GEMINI" or "CHATGPT"
# - "GENERATED BY"
# ,to add additional searching criteria

# Following each day generation (to avoid issues if the signal is unstable/other technical issues occure)
# generate the new 're-do' files (containing just the description - without code)
#   you can do this by stopping at CODE (no # at the start of the line - ignoring the spaces) and " ''' "
# and add the link to them onto the main README file

#!/usr/bin/env python3
"""
Daily LeetCode challenge: build 're-do' files (description only, no code)
for every file in the year folder that looks AI-generated.

Usage:
    python scripts/generate_redo.py                 # current year
    python scripts/generate_redo.py --year 2026
    python scripts/generate_redo.py --root . --readme README.md
"""
import argparse
import re
import sys
from datetime import datetime
from pathlib import Path
from urllib.parse import quote

# Case-insensitive substring checks (".ai" may be attached to other text).
# NOTE: ".ai" also matches things like "x.aid" or "self.air". If that causes
# false positives, swap it for r"\.ai\b" in AI_PATTERNS below.
AI_PATTERNS = [
    re.compile(re.escape(".ai"), re.I),
    re.compile(r"claude", re.I),
    re.compile(r"gemini", re.I),
    re.compile(r"chatgpt", re.I),
    re.compile(r"generated by", re.I),
]

REDO_DIR = "redo"  # outside the year folder so redo files are never re-scanned
README_START = "<!-- REDO-LINKS-START -->"
README_END = "<!-- REDO-LINKS-END -->"


def read_text(path: Path):
    """Return file text, or None if it looks binary / unreadable."""
    try:
        raw = path.read_bytes()
    except OSError:
        return None
    if b"\x00" in raw:
        return None
    return raw.decode("utf-8", errors="ignore")


def looks_ai_generated(text: str) -> bool:
    return any(p.search(text) for p in AI_PATTERNS)


def extract_description(text: str) -> str:
    """
    Keep everything from the top of the file until the first line of real CODE.
    Kept: blank lines, lines starting with '#' (ignoring leading spaces),
    and complete ''' / \"\"\" blocks. Stops at the first other line.
    """
    kept, delim = [], None
    for line in text.splitlines():
        s = line.strip()
        if delim:  # inside a ''' block
            kept.append(line)
            if delim in s:
                delim = None
            continue
        if s == "" or s.startswith("#"):
            kept.append(line)
            continue
        m = re.match(r"^('''|\"\"\")", s)
        if m:
            kept.append(line)
            d = m.group(1)
            if s.count(d) < 2:  # block continues on following lines
                delim = d
            continue
        break  # first real code line
    return "\n".join(kept).rstrip() + "\n" if kept else ""


def add_readme_link(readme: Path, label: str, rel_path: str) -> None:
    """Idempotently add '- [label](path)' between the README markers."""
    content = readme.read_text(encoding="utf-8") if readme.exists() else ""
    if README_START not in content or README_END not in content:
        content = content.rstrip() + f"\n\n## Re-do files\n\n{README_START}\n{README_END}\n"
    link = f"- [{label}]({quote(rel_path)})"
    if link in content:
        return
    content = content.replace(README_END, f"{link}\n{README_END}")
    readme.write_text(content, encoding="utf-8")


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--root", default=".", help="repo root")
    ap.add_argument("--year", default=str(datetime.now().year), help="year folder name")
    ap.add_argument("--readme", default="README.md")
    args = ap.parse_args()

    root = Path(args.root)
    year_dir = root / args.year
    readme = root / args.readme

    if not year_dir.is_dir():
        print(f"Year folder not found: {year_dir}", file=sys.stderr)
        return 1

    created = skipped = 0
    for month_dir in sorted(p for p in year_dir.iterdir() if p.is_dir()):
        for f in sorted(p for p in month_dir.iterdir() if p.is_file()):
            text = read_text(f)
            if text is None or not looks_ai_generated(text):
                skipped += 1
                continue

            description = extract_description(text)
            if not description.strip():
                print(f"[warn] no description found: {f}")
                skipped += 1
                continue

            out = root / REDO_DIR / args.year / month_dir.name / f"{f.stem}_redo{f.suffix}"
            out.parent.mkdir(parents=True, exist_ok=True)
            out.write_text(description, encoding="utf-8")

            # Update README straight away so progress survives a mid-run failure
            add_readme_link(readme, f"{month_dir.name}/{f.name}", out.relative_to(root).as_posix())
            created += 1
            print(f"[ok] {f} -> {out}")

    print(f"\nDone. Created {created} redo file(s), skipped {skipped}.")
    return 0


if __name__ == "__main__":
    sys.exit(main())